const d = $input.first().json;

return [{
  json: {
    document: {
      document_template_id: d.pdfMonkeyTemplateId,
      status: 'pending',
      meta: { _filename: d.pdfFilename },
      payload: {
        pages_html: d.pages_html
      }
    }
  }
}];

// Poll PDFMonkey until the document is ready; max 30s
// Also MERGE with Prepare PDFMonkey Data so we keep amazonOrderId/pdfFilename/etc.
const createResp = $input.first().json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;

if (!docId) {
  throw new Error('PDFMonkey create response missing id');
}

const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const http = this.helpers.httpRequest;

// Use the same API token as the create step
// NOTE: Replace with env/credential if available
const AUTH_HEADER = { Authorization: 'Bearer 2zpxHdmsse2ECXgVVtVR' };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;

async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 15) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method: 'GET', url: apiBase + docId, json: true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++;
  await sleep(2000);
}

if (status !== 'success' || !downloadUrl) {
  throw new Error(`PDFMonkey document not ready after polling (status=${status})`);
}

// Merge in the context from Prepare PDFMonkey Data and earlier nodes
let ctx = {};
try {
  ctx = $items('Prepare PDFMonkey Data', 0, 0)?.[0]?.json || {};
} catch {}

// Try to get pdfFilename and amazonOrderId from Generate Complete HTML
let htmlCtx = {};
try {
  htmlCtx = $items('Generate Complete HTML', 0, 0)?.[0]?.json || {};
} catch {}

// Also try Build Assembly Input From Manifest for amazonOrderId
let manifestCtx = {};
try {
  manifestCtx = $items('Build Assembly Input From Manifest', 0, 0)?.[0]?.json || {};
} catch {}

// Preserve pdfFilename and amazonOrderId (prioritize htmlCtx, then manifestCtx, then ctx)
const pdfFilename = htmlCtx.pdfFilename || ctx.pdfFilename || 'complete_book_ORDER.pdf';
const amazonOrderId = htmlCtx.amazonOrderId || manifestCtx.amazonOrderId || ctx.amazonOrderId || null;


// Construct pdfR2Key for upload
const pdfR2Key = `book-mvp-simple-adventure/orders/${amazonOrderId}/${pdfFilename}`;

return [{
  json: {
    ...ctx,
    ...manifestCtx,
    ...htmlCtx,
    pdfFilename,
    amazonOrderId,
    pdfMonkeyDocumentId: docId,
    pdfDownloadUrl: downloadUrl,
    pdfR2Key: pdfR2Key
  }
}];

/**
 * Prepare PDF Metadata for Merge
 * Strips binary data and passes only metadata to merge node
 */
const input = $input.first().json;
const amazonOrderId = input.amazonOrderId;
const pdfFilename = input.pdfFilename;
const pdfR2Key = input.pdfR2Key;

if (!amazonOrderId || !pdfFilename || !pdfR2Key) {
  throw new Error('Missing required PDF metadata: amazonOrderId, pdfFilename, or pdfR2Key');
}

console.log(`✓ PDF uploaded to R2: ${pdfR2Key}`);

return [{
  json: {
    amazonOrderId,
    characterHash: input.characterHash,
    pdfComplete: true,
    pdfFilename,
    pdfR2Key,
    pdfUploadedAt: new Date().toISOString(),
    // Preserve any other order context needed downstream
    characterSpecs: input.characterSpecs,
    bookSpecs: input.bookSpecs,
    orderDetails: input.orderDetails,
    backendUrl: input.backendUrl
  }
  // Note: No binary data - it's already uploaded to R2
}];

const order = $input.first().json;
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url = order.publicR2Url || null;

const completed = {
  ...order,
  status: 'book_assembly_completed',
  bookAssemblyCompletedAt: new Date().toISOString(),
  finalBookUrl: `${publicR2Url}/little-hero-orders/${order.amazonOrderId}/${order.pdfFilename}`,
  totalAssemblyTime: order.assemblyStartedAt ? (new Date() - new Date(order.assemblyStartedAt)) : null,
  averageTimePerPage: order.assemblyStartedAt
    ? Math.round(((new Date() - new Date(order.assemblyStartedAt)) / (order.totalPagesRequired || 14)) / 1000)
    : null
};

console.log(`Book assembly completed: ${order.amazonOrderId}`);
return [{ json: completed }];

/**
 * Build 3 Manifest — minimal, reference-only to Stage-2B
 * Creates the final manifest with book assembly results
 * Input: merged data from preview + PDF paths
 */

const input = $input.first().json || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

const pagePreviewImages = input.pagePreviewImages || [];
const pdfFilename = input.pdfFilename || null;
const pdfR2Key = input.pdfR2Key || null;
const amazonOrderId = input.amazonOrderId || null;

// ---- Required checks
if (!amazonOrderId) throw new Error('amazonOrderId is required for building 3-manifest');
if (!pdfR2Key)     throw new Error('pdfR2Key is missing — PDF may not have been uploaded');
if (!pdfFilename)  throw new Error('pdfFilename is missing');
if (!pagePreviewImages || pagePreviewImages.length === 0) {
  console.warn('⚠️ No pagePreviewImages found — preview images may have failed');
}

// ---- Retrieve 2B manifest JSON (for identity + order) and discover its storage reference
let manifest2B = null;
let upstreamRef = {
  posesManifestR2Key: null,
  posesManifestUrl:   null,
  schema:             null,
  runStamp:           null,
  characterHash:      null,
};

try {
  const dl = $items('Download 2B Manifest', 0, runIx);
  if (dl && Array.isArray(dl) && dl.length > 0) {
    const raw = dl[0] || {};
    const j = raw.json || {};

    // If the node returns the manifest JSON directly, capture minimal identity
    if (j && j.schema && String(j.schema).includes('lhb.run-manifest')) {
      manifest2B = j;
      upstreamRef.schema        = j.schema || null;
      upstreamRef.runStamp      = j.runStamp || null;
      upstreamRef.characterHash = j.characterHash || null;
    }

    // Heuristic probes for a stored reference (R2 key / public URL) that some HTTP/R2 nodes include
    upstreamRef.posesManifestR2Key =
        j.r2Key
     || j.manifestR2Key
     || j.r2_key
     || j.r2_path
     || j.key
     || j.sourceKey
     || null;

    upstreamRef.posesManifestUrl =
        j.publicUrl
     || j.url
     || j.presignedUrl
     || j.signedUrl
     || j.downloadUrl
     || null;
  }
} catch (e) {
  console.warn(`⚠️ Could not retrieve Stage-2B manifest reference: ${e.message}`);
}

if (!manifest2B || !manifest2B.schema) {
  throw new Error('2B manifest not found. Cannot build 3-manifest without Stage-2B.');
}

// ---- Basic totals
const totalPages = pagePreviewImages.length || 14;

// ---- Build 3-manifest WITHOUT copying pose/entries/counter blocks from 2B
// Keep the order section, identity, and a lightweight upstream reference to 2B.
const nowIso = new Date().toISOString();

const manifest3 = {
  schema: 'lhb.run-manifest@v2.0',
  runStamp: nowIso,

  // identity
  characterHash: input.characterHash || manifest2B.characterHash || null,

  // order block: prefer the fully-populated one from 2B to remain canonical
  order: manifest2B.order || {
    amazonOrderId,
    publicR2Url: input.publicR2Url || null,
  },

  // Upstream references instead of duplicating pose data/counters/entries
  upstream: {
    stage2: upstreamRef, // { posesManifestR2Key, posesManifestUrl, schema, runStamp, characterHash }
  },

  // Book assembly results (this stage’s product)
  bookAssembly: {
    completedAt: nowIso,
    pdfFilename,
    pdfR2Key,
    totalPages,
    pagePreviewImages,
  },

  // Workflow + summary for this stage only
  workflow: {
    currentStage: '3-complete',
    nextWorkflow: null,
    requiresHumanReview: false,
  },
  summary: {
    percentComplete: 100,
    readyForBook: true,
    needsHumanReview: false,
  },

  generatedAt: nowIso,
};

console.log('✓ 3-Manifest built successfully (reference-only to Stage-2B).');

return [{
  json: {
    manifest: manifest3,
    orderId: amazonOrderId,
    characterHash: manifest3.characterHash,
    pagePreviewImages,
    pdfFilename,
    pdfR2Key,
  }
}];

/**
 * Prep Manifest Upload (3) - Convert manifest to binary format for R2 upload
 */
const data = $input.first().json;
const manifest = data.manifest;
const orderId = data.orderId;

if (!manifest || !manifest.schema) {
  throw new Error('Manifest is missing or invalid in Prep Manifest Upload (3)');
}

if (!orderId) {
  throw new Error('orderId is required for Prep Manifest Upload (3)');
}

// Construct R2 key for 3-manifest
const manifestKey = `book-mvp-simple-adventure/orders/${orderId}/manifests/3-manifest.json`;

console.log(`Preparing to upload 3-manifest to: ${manifestKey}`);

// Convert manifest to buffer for upload
const manifestJSON = JSON.stringify(manifest, null, 2);
const buffer = Buffer.from(manifestJSON, 'utf-8');

return [{
  json: {
    ...data,
    manifestKey: manifestKey,
    manifestBucket: 'little-hero-orders'
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: '3-manifest.json',
      fileExtension: 'json'
    }
  }
}];

const order = $input.first().json;

const logEntry = {
  timestamp: new Date().toISOString(),
  workflow: '3-book-assembly-voice-of-wonder',
  orderId: order.amazonOrderId,
  status: order.status,
  pagesGenerated: order.pagesGenerated,
  totalPagesRequired: order.totalPagesRequired,
  assemblyProgress: order.assemblyProgress,
  finalBookUrl: order.finalBookUrl || 'N/A'
};

console.log('Book Assembly Results:', JSON.stringify(logEntry, null, 2));
return [{ json: logEntry }];
